export class DiGraph {
  constructor() {
    this._adj = new Map(); // node -> Set of successor nodes
  }

  addEdge(u, v) {
    if (!this._adj.has(u)) this._adj.set(u, new Set());
    if (!this._adj.has(v)) this._adj.set(v, new Set());
    this._adj.get(u).add(v);
  }

  addEdgesFrom(edgeArray) {
    for (const [u, v] of edgeArray) this.addEdge(u, v);
  }

  nodes() {
    return this._adj.keys();
  }

  successors(v) {
    return this._adj.get(v) ?? new Set();
  }
}

