const WHITE = 0; // unvisited
const GRAY = 1;  // on the current DFS stack
const BLACK = 2; // fully explored

export function isDirectedAcyclicGraph(G) {
  const color = new Map();
  for (const u of G.nodes()) color.set(u, WHITE);

  for (const start of G.nodes()) {
    if (color.get(start) !== WHITE) continue;

    // Iterative DFS; stack holds [node, iterator over its successors].
    const stack = [[start, G.successors(start)[Symbol.iterator]()]];
    color.set(start, GRAY);

    while (stack.length > 0) {
      const [u, it] = stack[stack.length - 1];
      const next = it.next();
      if (next.done) {
        color.set(u, BLACK);
        stack.pop();
      } else {
        const v = next.value;
        const c = color.get(v);
        if (c === GRAY) return false; // back edge -> cycle (covers self-loops)
        if (c === WHITE) {
          color.set(v, GRAY);
          stack.push([v, G.successors(v)[Symbol.iterator]()]);
        }
      }
    }
  }
  return true;
}

