import { basename } from 'node:path';
import { parseArgs } from './lib/argparse.mjs';
import { DiGraph } from './lib/digraph.mjs';
import { isDirectedAcyclicGraph } from './lib/dag.mjs';

const prog = basename(process.argv[1]);

const spec = [
  { name: '--a', dest: 'a', type: 'int', required: true },
  { name: '--b', dest: 'b', type: 'int', required: true },
  { name: '--c', dest: 'c', type: 'int', required: true },
  { name: '--d', dest: 'd', type: 'int', required: true },
  { name: '--e', dest: 'e', type: 'int', required: true },
];

const args = parseArgs(process.argv.slice(2), spec, prog);

const G = new DiGraph();
G.addEdgesFrom([
  [args.a, args.b],
  [args.b, args.c],
  [args.c, args.d],
  [args.d, args.e],
]);

console.log(isDirectedAcyclicGraph(G) ? 'True' : 'False');

