// Minimal argparse-compatible CLI parser (Python argparse behavior subset).
// Pure ESM, zero dependencies.

function usageLine(prog, spec) {
  const parts = [`usage: ${prog} [-h]`];
  for (const arg of spec) {
    const metavar = arg.dest.toUpperCase();
    const token = `${arg.name} ${metavar}`;
    parts.push(arg.required ? token : `[${token}]`);
  }
  return parts.join(' ');
}

function errorExit(prog, spec, message) {
  process.stderr.write(usageLine(prog, spec) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelp(prog, spec) {
  const lines = [usageLine(prog, spec), '', 'options:', '  -h, --help  show this help message and exit'];
  for (const arg of spec) {
    lines.push(`  ${arg.name} ${arg.dest.toUpperCase()}`);
  }
  process.stdout.write(lines.join('\n') + '\n');
  process.exit(0);
}

// Mimic Python's int(): optional surrounding whitespace, optional sign, decimal digits only.
function parseIntLikePython(raw) {
  const s = String(raw).trim();
  if (!/^[+-]?\d+$/.test(s)) return null;
  return parseInt(s, 10);
}

export function parseArgs(argv, spec, prog) {
  const byName = new Map(spec.map((arg) => [arg.name, arg]));
  const values = {};
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    let token = argv[i];

    if (token === '-h' || token === '--help') {
      printHelp(prog, spec);
    }

    let inlineValue = null;
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        inlineValue = token.slice(eq + 1);
        token = token.slice(0, eq);
      }
    }

    const arg = byName.get(token);
    if (!arg) {
      extras.push(argv[i]);
      continue;
    }

    let raw;
    if (inlineValue !== null) {
      raw = inlineValue;
    } else if (i + 1 < argv.length) {
      raw = argv[++i];
    } else {
      errorExit(prog, spec, `argument ${arg.name}: expected one argument`);
    }

    if (arg.type === 'int') {
      const n = parseIntLikePython(raw);
      if (n === null) {
        errorExit(prog, spec, `argument ${arg.name}: invalid int value: '${raw}'`);
      }
      values[arg.dest] = n;
    } else {
      values[arg.dest] = raw;
    }
  }

  const missing = spec.filter((arg) => arg.required && !(arg.dest in values)).map((arg) => arg.name);
  if (missing.length > 0) {
    errorExit(prog, spec, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    errorExit(prog, spec, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

