node -e "
import('/output/lib/digraph.mjs').then(async ({DiGraph}) => {
  const {isDirectedAcyclicGraph} = await import('/output/lib/dag.mjs');
  const G1 = new DiGraph();
  G1.addEdgesFrom([[1,2],[2,3],[3,4],[4,5]]);
  console.log('acyclic:', isDirectedAcyclicGraph(G1));
  const G2 = new DiGraph();
  G2.addEdgesFrom([[1,2],[2,3],[3,4],[4,5],[2,2]]); // self-loop b=b
  console.log('selfloop:', isDirectedAcyclicGraph(G2));
  const G3 = new DiGraph();
  G3.addEdgesFrom([[1,2],[2,3],[3,1]]);
  console.log('cycle:', isDirectedAcyclicGraph(G3));
  const G4 = new DiGraph();
  console.log('empty:', isDirectedAcyclicGraph(G4));
});"

